# helpers
def get_index(value, table, start, end):
    try:
        i = table.index(value, start, end)
        return i
    except ValueError:
        return -1


# helpers for cpython
from time import time


def monotonic():
    return int(time() * 1000)


def ticks_diff(a, b):
    return a - b


def ticks_add(a, inc):
    return a + inc
